class SalaryHistory {
  std::map<std::chrono::sys_days, Money> byStart_;      // effective date -> amount
public:
  Money at(std::chrono::sys_days when) const {
    auto it = byStart_.upper_bound(when);               // first milestone after `when`
    if (it == byStart_.begin()) throw std::out_of_range("no salary effective yet");
    return std::prev(it)->second;                       // latest milestone <= `when`
  }
  Money current() const;   // at(floor<days>(system_clock::now()))
  void put(std::chrono::sys_days from, Money amount) { byStart_[from] = amount; }
};
